            }

            // Prepare API request
            const url = `${this.baseUrl}/crypto/prices`;
            const headers = {
                'Content-Type': 'application/json',
                'Accept': 'application/json'
            };

            // Add API key if provided
            if (this.apiKey) {
                headers['Authorization'] = `Bearer ${this.apiKey}`;
            }

            const requestBody = {
                symbols: symbols,
                currency: currency,
                timestamp: Date.now()
            };

            // Make API request
            const response = await fetch(url, {
                method: 'POST',
                headers: headers,
