class FxBinaryInvestProClient {
  constructor() {
    this.baseURL = process.env.FXBINARY_API_URL || 'https://api.fxbinaryinvestpro.com';
    this.apiKey = process.env.FXBINARY_API_KEY;
    this.apiSecret = process.env.FXBINARY_API_SECRET;

