                lastError = error;
                if (attempt < this.retryAttempts) {
                    await this.delay(Math.pow(2, attempt) * 1000); // Exponential backoff
                }
            }
        }

        throw new Error(`Request failed after ${this.retryAttempts} attempts: ${lastError.message}`);
