                </div>
                <div class="upload-results" id="smartload-results"></div>
            </div>
        `;

        this.addStyles();
    }

    /**
     * Add widget styles
     */
    addStyles() {
        const style = document.createElement('style');
        style.textContent = `
            .smartload-upload-area {
