    {
        try {
            $cacheKey = 'clothing_items_' . md5(serialize($filters));
            $cachedData = $this->getCachedData($cacheKey);

            if ($cachedData !== null) {
                return $cachedData;
            }

            $url = self::API_BASE_URL . '/merchandise/clothing';
